package com.xiaomiscalesync.xiaomi

import com.google.gson.JsonParser
import com.xiaomiscalesync.crypto.Vectors

/**
 * One fixture from the committed `micloud_vectors.json`
 * (generated by `scripts/gen_vectors.py --micloud`).
 */
sealed class MiCloudVector {
    abstract val name: String

    /**
     * RC4 known answer. [drop] is the number of leading keystream bytes the
     * reference client discards before use (`r.encrypt(bytes(1024))`): 0 for
     * the published raw-RC4 vectors, 1024 for the `encrypt_rc4` /
     * `decrypt_rc4` transform.
     */
    data class Rc4(
        override val name: String,
        val drop: Int,
        val key: ByteArray,
        val plaintext: ByteArray,
        val ciphertext: ByteArray,
    ) : MiCloudVector()

    /** The full Mi Cloud request-signing chain (`generate_enc_params`). */
    data class Sign(
        override val name: String,
        val ssecurity: String,
        val nonceRandom: ByteArray,
        val nonce: String,
        val millis: Long,
        val url: String,
        val method: String,
        val signedNonce: String,
        val params: Map<String, String>,
        val encParams: Map<String, String>,
        val responsePlaintext: String,
        val responseCiphertext: String,
    ) : MiCloudVector()
}

/** Loads `micloud_vectors.json` from the unit-test resources. */
object MiCloudVectors {

    fun load(): List<MiCloudVector> {
        val url = checkNotNull(
            MiCloudVectors::class.java.classLoader?.getResource("micloud_vectors.json")
        ) { "missing test resource micloud_vectors.json" }
        val array = url.openStream().bufferedReader().use { reader ->
            JsonParser.parseReader(reader).asJsonArray
        }
        return array.map { element ->
            val obj = element.asJsonObject
            when (val type = obj.get("type").asString) {
                "rc4", "rc4_drop1024" -> MiCloudVector.Rc4(
                    name = obj.get("name").asString,
                    drop = if (type == "rc4") 0 else 1024,
                    key = Vectors.decodeHex(obj.get("key").asString),
                    plaintext = Vectors.decodeHex(obj.get("plaintext").asString),
                    ciphertext = Vectors.decodeHex(obj.get("ciphertext").asString),
                )
                "mi_sign" -> MiCloudVector.Sign(
                    name = obj.get("name").asString,
                    ssecurity = obj.get("ssecurity").asString,
                    nonceRandom = Vectors.decodeHex(obj.get("nonceRandom").asString),
                    nonce = obj.get("nonce").asString,
                    millis = obj.get("millis").asLong,
                    url = obj.get("url").asString,
                    method = obj.get("method").asString,
                    signedNonce = obj.get("signedNonce").asString,
                    params = stringMap(obj.getAsJsonObject("params")),
                    encParams = stringMap(obj.getAsJsonObject("encParams")),
                    responsePlaintext = obj.get("responsePlaintext").asString,
                    responseCiphertext = obj.get("responseCiphertext").asString,
                )
                else -> error("unknown fixture type '$type' in micloud_vectors.json")
            }
        }
    }

    /** Preserves the fixture's key order (it is part of the wire contract). */
    private fun stringMap(json: com.google.gson.JsonObject): Map<String, String> {
        val out = LinkedHashMap<String, String>()
        json.entrySet().forEach { out[it.key] = it.value.asString }
        return out
    }
}
